-- 용마산 전체 seed data
-- 원본: 산림청 등산로정보 PMNTN / PMNTN_SPOT (원본 SHP·SHX·DBF·PRJ)
-- 산 코드: 112600501(용마산)
-- 원본 건수: PMNTN 123피처, PMNTN_SPOT 169피처
-- 적재 건수: raw_trail 123건, trail_spot 169건
-- 모든 원본 등산로가 LineString이므로 123건을 그대로 적재한다.
-- 원본 좌표계: PCS_ITRF2000_TM (.prj; EPSG:5186과 일치하는 TM 파라미터)
-- DB 저장 좌표계: EPSG:5179
-- 원본 기준일: 2016-12-31, 수집일: 2026-11-23
--
-- 이 파일은 신규 용마산 seed 최초 실행 전용이다.
-- 실행 도구: PostgreSQL psql -f (COPY FROM stdin 포함). DBeaver 일반 스크립트 실행은 비권장.
-- 정상 적재 전제: PostGIS/pgRouting 및 ORDA 스키마 설치 완료.
-- 원본 파일: 각 SHP 구성요소 4개를 결합한 SHA256 기록 (원본 ZIP 해시 아님).
-- 대표 위치는 등산로 좌표 범위의 중심이며 정상 위치/고도는 미검증(NULL).
-- 산·원천 데이터·네트워크·서비스 영역·태그·지점 매칭을 한 트랜잭션으로 처리한다.
-- 기존 관악산 seed와 Flyway migration은 변경하지 않는다.

BEGIN;

-- 같은 이름의 활성 산이 있으면 기존 참조를 보호하기 위해 중단한다.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.mountain
        WHERE mountain_nm = '용마산'
          AND use_yn = 'Y'
    ) THEN
        RAISE EXCEPTION '활성 용마산 데이터가 이미 존재합니다. 이 seed는 최초 실행 전용입니다.';
    END IF;
END
$$;

INSERT INTO public.mountain (
    mountain_nm, src_mntn_cd, src_old_mntn_cd, use_yn,
    province_nm, district_nm, address_label, elevation_m, representative_geom
) VALUES (
    '용마산', '112600501', NULL, 'Y',
    '서울특별시', '중랑구',
    '서울특별시 용마산', NULL,
    ST_SetSRID(ST_MakePoint(964276.149141, 1952891.403691), 5179)
);

SELECT set_config('orda.seed.mountain_id', mountain_id::text, true)
FROM public.mountain
WHERE mountain_nm = '용마산'
  AND use_yn = 'Y';

