    ('derived:yongma:service_area', 'DERIVED', 'SERVICE_AREA', 'project development seed', NULL, NULL, DATE '2026-11-23', 'EPSG:5179', 'yongma_seed.sql', NULL, NULL, 'network-buffer-200m-v1', '용마산 통행 가능 trail_edge에 200m 버퍼를 적용하고 내부 구멍을 제거한 서비스 가능 영역.')
ON CONFLICT (dataset_nm, data_ver) DO NOTHING;

-- 원천 등산로를 임시 테이블에 적재한 뒤 이름으로 찾은 FK와 연결한다.
CREATE TEMP TABLE tmp_yongma_raw_seed (
    dataset_nm varchar(100),
    src_trail_id varchar(20),
    trail_nm varchar(100),
    src_length_m numeric(9,1),
    src_difficulty_nm varchar(10),
    src_uphill_min integer,
    src_downhill_min integer,
    src_surface_nm varchar(50),
    geom geometry(LineString,5179),
    use_yn char(1),
    exclude_rsn varchar(200),
    src_attr_json jsonb
) ON COMMIT DROP;

COPY tmp_yongma_raw_seed (
    dataset_nm, src_trail_id, trail_nm, src_length_m, src_difficulty_nm,
    src_uphill_min, src_downhill_min, src_surface_nm, geom, use_yn, exclude_rsn, src_attr_json
) FROM stdin;
