INSERT INTO public.raw_trail (
    dataset_id, mountain_id, src_trail_id, trail_nm, src_length_m, src_difficulty_nm,
    src_uphill_min, src_downhill_min, src_surface_nm, geom, use_yn, exclude_rsn, src_attr_json
)
SELECT
    dataset.dataset_id, current_setting('orda.seed.mountain_id')::integer, seed.src_trail_id, seed.trail_nm,
    seed.src_length_m, seed.src_difficulty_nm, seed.src_uphill_min, seed.src_downhill_min,
    seed.src_surface_nm, seed.geom, seed.use_yn, seed.exclude_rsn, seed.src_attr_json
FROM tmp_yongma_raw_seed AS seed
JOIN public.source_dataset AS dataset
  ON dataset.dataset_nm = seed.dataset_nm
 AND dataset.data_ver = 'sha256:075fc93c6c6d025c'
ON CONFLICT (dataset_id, src_trail_id) DO NOTHING;

-- 상세지점을 같은 방식으로 적재한다.
CREATE TEMP TABLE tmp_yongma_spot_seed (
    dataset_nm varchar(100),
    src_spot_id varchar(20),
    src_old_spot_id varchar(14),
    src_class_cd varchar(2),
    src_class_nm varchar(50),
    detail_txt varchar(200),
    etc_txt varchar(200),
    geom geometry(Point,5179),
    src_attr_json jsonb
) ON COMMIT DROP;

COPY tmp_yongma_spot_seed (
    dataset_nm, src_spot_id, src_old_spot_id, src_class_cd, src_class_nm,
    detail_txt, etc_txt, geom, src_attr_json
